class LogSystem {
    vector<pair<string, int>> logs;
    unordered_map<string, int> width = {
        {"Year", 4}, {"Month", 7}, {"Day", 10},
        {"Hour", 13}, {"Minute", 16}, {"Second", 19}
    };

public:
    LogSystem() {}

    void put(int id, string timestamp) {
        logs.push_back({timestamp, id});
    }

    vector<int> retrieve(string start, string end, string granularity) {
        int length = width[granularity];
        vector<int> result;
        for (const auto& log : logs) {
            string prefix = log.first.substr(0, length);
            if (prefix >= start.substr(0, length) &&
                prefix <= end.substr(0, length)) {
                result.push_back(log.second);
            }
        }
        return result;
    }
};
